"""Canonical manuscript notes layered over the currently mounted route inventory.

This data is consumed by api2paper.py. Keys are HTTP method plus full path.
No credentials or account role literals belong here.
"""
CONTRACTS = {}


def add(method, path, title, parameters="None.", response="See the named fields in the response description.", notes="", example=None, errors="", status=200):
    CONTRACTS[f"{method} {path}"] = dict(title=title, parameters=parameters, response=response, notes=notes, example=example, errors=errors, status=status)


P = "/api/v1"
YEAR = "Year levels use FIRST, SECOND, THIRD, FOURTH, FIFTH. An empty year-level list means unrestricted responsibility within the department's offered levels."
PAGING = "Optional query: page (positive integer, default 1), pageSize or limit (default 50, maximum 200). Some small-list endpoints return the full list with paging metadata rather than slicing; see endpoint notes."
SUBMISSIONS = "Optional query: step (ASSESSMENT, SOCIAL_MEDIA, PROFILING, MUGSHOT, CONSENT); page (default 1), pageSize (1–100, default 50); sort (submittedAt, studentName, status; default submittedAt); dir (asc/desc, default asc); q (up to 100 characters); status (ALL, PENDING, SUBMITTED, VERIFIED, RETURNED); evidence (ALL, HAS, NONE); range (ALL, today, 7d, 30d, year)."
DIRECTORY = "Optional query: q (up to 100 characters), role (permitted account category; omit for all), outside (ALL/INSIDE/OUTSIDE), academicYearId, departmentId, yearLevel; sort (joined/studentNumber/name, default joined), dir (asc/desc, default desc). Account-category labels in this document are descriptive, not wire values; use the account-management client for role-filtered requests."
ROSTER = "Optional query: academicYearId; scope (mine/all, default mine); sort (name/studentNumber/stepsVerified/yearLevel/enrolledAt); dir (asc/desc); q (up to 100 characters); departmentIds, yearLevels, buckets, steps (repeat array query keys for multiple selections); stepState; enrolled (true/false); unassigned (true). Buckets: NOT_STARTED, IN_PROGRESS, READY_FOR_QUEUE, ENROLLED. Step states: MISSING, PENDING, SUBMITTED, VERIFIED, RETURNED. Scope all is a roster filter, not an access-control bypass."

add("GET", P+"/academic-years", "List Academic Years", PAGING, "data: [{ id, label, semesterLabel, isActive, createdAt, hasData }], with list metadata", "Returns the complete year list with paging metadata.")
add("POST", P+"/academic-years", "Create an Academic Year", "Body: label and semesterLabel (required trimmed strings, 1–30 characters); activate (boolean, default false).", "data: { id, label, semesterLabel, isActive }", "Activation is refused while another current year still has waiting or served students.", {"label":"2026–2027","semesterLabel":"First Semester","activate":False}, status=201, errors="409 if activation would interrupt an open queue.")
add("PATCH", P+"/academic-years/:id", "Edit the Current Academic Year", "Path: id. Body: label and semesterLabel (both required, 1–30 characters).", "data: { id, label, semesterLabel }", "Only the active year can be edited.", {"label":"2026–2027","semesterLabel":"First Semester"}, "403 for an inactive year; 404 if missing.")
add("DELETE", P+"/academic-years/:id", "Delete an Empty Academic Year", "Path: id.", "data: { id }", errors="404 if missing; 409 if verification, queue, or profiling-form records exist.")
add("GET", P+"/academic-years/:id/activation", "Preview Academic-Year Activation", "Path: id.", "data: { currentYearLabel, studentsWithProgress, openQueueCount }", errors="404 if year is missing.")
add("POST", P+"/academic-years/:id/activation", "Activate an Academic Year", "Path: id. No business body fields.", "data: { id, label, semesterLabel }", "Activates this year and deactivates the others. Repeating activation of the active year is accepted.", errors="404 if missing; 409 while the current year has an open queue.")
add("GET", P+"/requirements", "List Assessment Requirements", PAGING, "data: [{ id, label, order, isActive }], with list metadata", "Returns the complete requirement list with paging metadata.")
add("POST", P+"/requirements", "Add an Assessment Requirement", "Body: label (required trimmed string, 1–200 characters).", "data: { id, label, order, isActive }", example={"label":"Assessment balance checked"}, status=201)
add("PUT", P+"/requirements/order", "Reorder Assessment Requirements", "Body: orderedIds (required array of nonempty identifiers, at most 500).", "data: { orderedIds }", "Unlisted existing items are appended. The response is the submitted identifier list, not full requirement rows.", {"orderedIds":["requirement-example"]}, "404 for unknown identifiers.")
add("PATCH", P+"/requirements/:id", "Update an Assessment Requirement", "Path: id. Body: label (optional, 1–200 characters), isActive (optional boolean).", "data: { id, label, order, isActive }", example={"isActive":False}, errors="404 if missing.")
add("DELETE", P+"/requirements/:id", "Delete an Assessment Requirement", "Path: id.", "data: { id }", errors="404 if missing.")

add("GET", P+"/reports/user-directory", "Read User-Directory Report Data", DIRECTORY, "data: { year, rows, matchedCount, truncated }", "At most 1,000 rows. The API returns JSON; PDF layout, preview, and download happen in the website.")
add("GET", P+"/reports/roster", "Read Department-Roster Report Data", ROSTER, "data: { year, rows, stats, matchedCount, truncated }", "At most 1,000 rows. Embedded stats summarize the returned rows. The separate roster-stats endpoint is uncapped but deliberately ignores bucket filters, so its totals may differ from a bucket-filtered report. Without a year, returns empty rows and year null.")
add("GET", P+"/reports/roster-stats", "Read Uncapped Roster Totals", ROSTER, "data: { year, stats: { byCourse, byCourseYearLevel, distribution, unassignedTotal, total } }", "Aggregates without the PDF row cap and deliberately ignores buckets. Other applicable roster filters remain; totals are not necessarily the count of a bucket-filtered report.")
add("GET", P+"/reports/step-register", "Read Step-Register Report Data", "Query: step is required. Other submission filters apply, except page and pageSize. "+SUBMISSIONS, "data: { year, step: { code, name }, rows, matchedCount, truncated }", "At most 1,000 rows. No PDF bytes are returned.")
add("GET", P+"/chatbot-knowledge", "Read Assistant Knowledge", response="data: { content, version, updatedById, updatedByName, updatedAt }, or null")
add("PUT", P+"/chatbot-knowledge", "Replace Assistant Knowledge", "Body: content (required string, up to 200,000 characters).", "data: { version, updatedAt }", "Increments the version and invalidates the assistant's knowledge cache.", {"content":"Ask an SBO officer when a requirement is unclear."})
add("GET", P+"/profiling-form", "Read the Linked Profiling Form", response="data: { formId, title, responderUri, editUrl, updatedByName, updatedAt }, or null")
add("POST", P+"/profiling-form", "Create and Link the Profiling Form", "Body: title (required trimmed string, 1–200 characters).", "data: linked form details", "Creates a verified-email-collection Google Form, publishes it, and shares it with the caller. It does not accept a replacement form URL.", {"title":"Student Profiling"}, "409 if already linked; 412 without an active year; 503 if Forms is off; provider failures can prevent creation.", 201)
add("DELETE", P+"/profiling-form", "Unlink the Profiling Form", response="data: { ok: true }", notes="Removes the current-year link, not the underlying Google Form.")
add("GET", P+"/social-links", "List Required Social-Media Links", PAGING, "data: ordered social-link rows, with list metadata", "Returns the complete ordered list with paging metadata.")
add("POST", P+"/social-links", "Add or Update a Social-Media Link", "Body: name (1–120 characters), url (valid URL, at most 1,000 characters); id (optional existing identifier).", "data: social-link row", "201 when creating; 200 when id selects an existing link.", {"name":"College page","url":"https://example.org/college"}, "404 for an unknown supplied id.", 201)
add("PUT", P+"/social-links/order", "Reorder Social-Media Links", "Body: orderedIds (required array of nonempty identifiers).", "data: { ok: true }", example={"orderedIds":["link-example"]})
add("PATCH", P+"/social-links/:id", "Edit a Social-Media Link", "Path: id. Body: name and url (both required; same limits as creation).", "data: social-link row", example={"name":"College page","url":"https://example.org/college"}, errors="404 if missing.")
add("DELETE", P+"/social-links/:id", "Delete a Social-Media Link", "Path: id.", "data: { ok: true }")
add("GET", P+"/signup-options", "Read Registration Options", response="data: { academicYears: [{ id, label, semesterLabel, isActive }], departments: [...] }", notes="Public. Year-level choices are represented by department data; the response is not a top-level yearLevels array.")
add("GET", P+"/me/launch", "Load the Landing-Screen Bundle", response="data: role-appropriate launch bundle", notes="All signed-in accounts. Cache-Control: private, no-store; Vary: Cookie. The bundle varies by the caller's working area.")
add("GET", P+"/me/overview", "Read the Officer or Administrator Overview", response="data: role-appropriate overview", notes="The administrator receives administrator statistics; the officer receives the officer overview. A session alone is insufficient.", errors="403 for users without officer or administrator overview permission.")
add("GET", P+"/me/stamp", "Read My Digital Stamp", response="data: stamp details")
add("PATCH", P+"/me/stamp", "Update My Digital Stamp", "Body: name (optional, at most 80 characters); graphicUrl and signatureUrl (optional URL up to 1,000 characters, or null).", "data: stamp details", example={"name":"Reviewing Officer","graphicUrl":None}, errors="404 if account cannot be updated.")
add("GET", P+"/me/notifications", "Read My Notifications", response="data: notification rows, page: 1, pageSize: 50, total: returned-row count", notes="Newest first, capped at 50. This handler does not expose arbitrary notification pagination. New read markers live in account-scoped browser storage, capped at 1,000 IDs; they do not synchronize across devices and clearing browser storage resets them. Existing server read markers remain honored. There is no mark-read write endpoint.")

add("GET", P+"/departments", "List Departments and Assignments", PAGING, "data: department rows with assignment information, with list metadata", "Administrators see all departments; advisers receive their applicable listing. This list is sliced by page.")
add("GET", P+"/me/departments", "Read My Student Department", response="data: department information with schedule { current, next }, or null")
add("PUT", P+"/me/departments", "Set My Department Responsibility", "Body: departmentIds (required array, at most one identifier), yearLevels (optional, at most five; default []). "+YEAR, "data: assignment result", "Checks offered levels and overlapping claims.", {"departmentIds":["department-example"],"yearLevels":["FIRST"]}, "409 if an existing holder overlaps; 400 for unsuitable offered levels.")
add("POST", P+"/departments", "Create a Department", "Body: name (required trimmed string, 1–120 characters).", "data: { id, name, code, yearLevels, isActive, assigned? }", "Code is derived from the name, not supplied. An adviser holding no department is assigned automatically; administrators do not receive that self-assignment.", {"name":"Information Technology"}, "409 if the name or derived code already exists.", 201)
add("PATCH", P+"/departments/:id", "Rename or Change Department Status", "Path: id. Body: name (optional, 1–120 characters), isActive (optional boolean). At least one field is required.", "data: changed department fields", "isActive is administrator-only. Do not assume every department action uses identical ownership checks.", {"name":"Information Technology"}, "403 for adviser status changes; 404 if missing; 409 for duplicate identity or deactivation with students in line.")
add("PUT", P+"/departments/:id/year-levels", "Set Offered Department Year Levels", "Path: id. Body: yearLevels (required array, at most five). "+YEAR, "data: { id, yearLevels }", "Requires the assigned adviser or an administrator.", {"yearLevels":["FIRST","SECOND"]}, "403 if not assigned; 404 if missing.")
add("DELETE", P+"/departments/:id", "Delete an Eligible Department", "Path: id.", "data: { id, deleted: true }", "Requires assignment or administrator permission. Cleans related availability, assignments, and schedules.", errors="403 if not assigned; 404 if missing; 409 if queue entries prevent deletion.")
add("GET", P+"/departments/:id/enrollments", "Read the Department Enrollment Register", "Path: id. Optional query: range (today/ay/all, default ay), q (up to 100 characters), cursor, limit (1–500, default 50).", "data: register entries, page: 1, pageSize: limit, total", "Read the X-Next-Cursor response header for continuation. Uses the current active academic year context.")
add("GET", P+"/advisers", "List Adviser Assignments", PAGING, "data: [{ id, name, email, departments: [{ id, name, code, yearLevels }] }], with list metadata", "Returns the complete roster with paging metadata.")
add("PATCH", P+"/advisers/:adviserId", "Replace an Adviser's Assignments", "Path: adviserId. Body: assignments (required array, at most 50) of { departmentId, yearLevels? }; levels default to []. "+YEAR, "data: assignment result", "Administrator-only. Replaces the whole mapping, not a partial append.", {"assignments":[{"departmentId":"department-example","yearLevels":["FIRST"]}]})
add("PUT", P+"/me/availability", "Open or Close My Queue Availability", "Body: departmentId (required identifier), isOpen (required boolean).", "data: { departmentId, myOpen, isOpen, openBy }", "Closing releases a student currently served by this adviser. isOpen can remain true if another adviser is open.", {"departmentId":"department-example","isOpen":True})
add("POST", P+"/me/availability/heartbeat", "Refresh My Availability", response="data: { touched }", notes="Refreshes the caller's open availability; no departmentId business body is required.")
add("GET", P+"/transfers", "List Incoming and Outgoing Handovers", response="data: transfer list", notes="Resolves expired requests first. Automatic response windows are ten minutes for an active holder and one minute for an inactive holder.")
add("POST", P+"/transfers", "Request Department or Year-Level Handover", "Body: departmentId (required), yearLevels (optional, default []). "+YEAR, "data: serialized transfer including its expiry and parties", "The caller requests responsibility from the overlapping current holder; do not supply ownerId or accept in this request.", {"departmentId":"department-example","yearLevels":["FIRST"]}, "409 if no overlapping holder exists or department is inactive; 412 without an active year.", 201)
add("PATCH", P+"/transfers/:id", "Accept or Decline a Handover", "Path: id. Body: accept (required boolean).", "data: { id, status, transferredFromName }", "Only the recorded owner may respond to a pending request.", {"accept":True}, "403 if not owner; 404 if missing; 409 if already resolved or ownership changed.")
add("DELETE", P+"/transfers/:id", "Cancel My Handover Request", "Path: id.", "data: { id, cancelled: true }", "Only the requester may cancel a pending request.", errors="403 if not requester; 404 if missing; 409 if resolved.")
add("POST", P+"/departments/:id/takeover", "Take Over Department Responsibility", "Path: id. Body: yearLevels (optional, default []). "+YEAR, "data: { departmentId, name, code, transferredFromName }", "Uses the current takeover service and offered-level checks; this is separate from accepting a pending transfer.", {"yearLevels":["FIRST"]})
add("GET", P+"/me/schedule", "Read My Department Office Hours", "Required query: departmentId.", "data: { departmentId, windows, sync }", "Returns the caller's windows for the current year. Past dated exceptions are filtered out. Does not open or close queue availability.")
add("PUT", P+"/me/schedule", "Replace Department Office Hours", "Body: departmentId and windows required. Input parsing allows at most 100 submitted entries; business validation permits at most 30 remaining entries after past dated exceptions are removed. Each item has kind WEEKLY, EXTRA, or CANCEL. WEEKLY requires weekday 1–7 (Monday–Sunday), startMinute, endMinute. EXTRA requires date YYYY-MM-DD and start/end minutes. CANCEL requires date. Timed values use a 30-minute grid, start >= 0, end <= 1440, with at least 30 minutes duration. Times use Asia/Manila.", "data: { departmentId, windows, sync }", "Replaces the complete schedule, including removal when windows is empty. Past dated exceptions are filtered before validation. May trigger optional calendar sync without changing live availability.", {"departmentId":"department-example","windows":[{"kind":"WEEKLY","weekday":1,"startMinute":540,"endMinute":660}]}, "400 for invalid windows or more than 30 retained entries; 403 if not assigned; 409 for overlapping windows.")
add("GET", P+"/me/calendar", "Read My Calendar Connection", response="data: { available, status, sync, googleEmail, lastSyncAt, lastError }")
add("GET", P+"/me/calendar/connect", "Start Calendar Authorization", response="data: { url }", notes="Open the returned Google consent URL. Limited to ten calendar requests per minute per account for connect/callback/sync.", errors="412 if integration is unavailable; 429 when rate limited.")
add("GET", P+"/calendar/callback", "Complete Calendar Authorization", "Query: code and state for successful authorization; error can be supplied by Google.", "302 Location: /instructor?calendar=connected or /instructor?calendar=error", "This is a redirect, not a JSON resource envelope. Missing/invalid consent data redirects to the error outcome after permission checks.", errors="401/403 for session/permission failure; 429 for the calendar limit.", status=302)
add("POST", P+"/me/calendar/sync", "Synchronize Calendar Again", response="data: calendar status", notes="Resets the retry count and requests another schedule synchronization.", errors="412 if unavailable; 429 for the calendar limit.")
add("DELETE", P+"/me/calendar", "Disconnect Calendar", response="data: calendar status", notes="Removes the mirrored calendar and stored connection token; office hours in ERPSYS remain.")

add("GET", P+"/me/queue", "Read My Queue Position", response="data: current queue state, or null")
add("POST", P+"/me/queue", "Join My Enrollment Queue", "Body: departmentId (required).", "data: { entryId, departmentName, position }", "Requires verified pre-enrollment steps, eligible course/year level, and a currently available adviser. Switching queues requires leaving the previous one first; opening a share link does not join automatically.", {"departmentId":"department-example"}, "409 for unmet prerequisites, unsuitable queue state, or unavailable service.", 201)
add("DELETE", P+"/me/queue", "Leave My Waiting Queue", response="data: { left: true }", notes="Repeated exit when no entry exists is accepted. A student being served cannot leave.", errors="409 while being served.")
add("GET", P+"/queues", "Monitor My Department Queues", response="data: department queues and serving state", notes="The current implementation uses resource reads; there is no mounted queue-event stream.")
for method, suffix, title, response in [
    ("POST","","Serve the Next Eligible Student","data: { entryId, status }"),
    ("DELETE","","Release the Served Student","data: { entryId, status }"),
    ("POST","/position","Move the Served Student to the End","data: { entryId, position }")]:
    add(method,P+"/queues/serving"+suffix,title,"Body: departmentId and entryId (required nonempty identifiers)."+(" Optional to: end." if suffix else ""),response,"Assignment, current service, and queue order are checked. Sending an arbitrary waiting entry does not bypass first-in-first-out service.",{"departmentId":"department-example","entryId":"queue-example"},"404 if entry is missing; 409 for a changed or unsuitable service state.",201 if method=="POST" and not suffix else 200)
add("POST", P+"/queue-entries/:id/removal", "Remove a Waiting Queue Entry", "Path: id. No business body fields.", "data: { removed, reason, snapshot: { entryId, departmentId, studentProfileId, academicYearId, joinedAt, studentName, token } }", "Only waiting entries may be removed. Keep the returned snapshot unchanged for Undo. A concurrent change can return removed false with a reason, not a successful deletion.", errors="404 if missing; 409 for served/completed or unsuitable entry state.")
add("POST", P+"/queue-entries/:id/restoration", "Restore a Removed Queue Entry", "Path: id. Body: departmentId, studentProfileId, academicYearId, joinedAt, studentName, token (all required; copy the removal snapshot).", "data: { restored: true, entryId }", "The website offers Undo for five seconds; server token validation allows a 60-second window. The token is signed for the removing adviser and snapshot. Restoration preserves joinedAt, not a client-selected queue number.", {"departmentId":"department-example","studentProfileId":"profile-example","academicYearId":"year-example","joinedAt":"2026-08-01T01:00:00.000Z","studentName":"Example Student","token":"<token from removal response>"}, "403 for invalid/expired token; 409 for a changed year or existing/rejoined entry; 404 for missing related data.")
add("POST", P+"/queue-shares", "Create a Queue Invitation", "Body: departmentId (required).", "data: { url, token, departmentId, departmentName, inviterName, academicYearId }", "Requires an assigned adviser, active department/year, and configured public site address. Links are tied to the academic year, not documented as a fixed-duration expiry.", {"departmentId":"department-example"}, "412 for missing or unsuitable public address/active year; 404 for missing/inactive department.", 201)
add("GET", P+"/queue-shares/:token", "Resolve a Queue Invitation", "Path: token (1–2,000 characters).", "data: { status, departmentId, departmentName, departmentCode, inviterName, isOpen, openByName, waitingCount, academicYearId }", "Invalid tokens return HTTP 200 with status INVALID. A different/no active year returns 200 with status STALE. Valid invitations return status OK even when isOpen is false; resolving never joins the queue.")
add("GET", P+"/audit-logs", "Search Recorded Write Requests", "Optional query: role (account category filter, at most 40 characters), method (POST/PUT/PATCH/DELETE), q (actor name, email, or path; at most 200 characters). "+PAGING, "data: [{ id, actorId, actorName, actorEmail, role, method, path, status, ip, at }], with list metadata", "Records signed-in versioned write requests, newest first. This request audit is separate from administrator action summaries.")
add("POST", "/api/chat/stream", "Stream an Enrollment Assistant Reply", "Body: messages (1–20 items), each { role, text }; role is user, assistant, or legacy model; text is 1–2,000 characters. JSON body limit 100 KB.", "200 text/event-stream: data frames containing start, token, done, or error objects", "Uses the signed-in student working area. Legacy model messages normalize to assistant. Ten requests per minute per account/IP; daily allowances and provider limits also apply. Errors after the stream starts are event objects, not a new HTTP status.", {"messages":[{"role":"user","text":"What should I do after my requirement is returned?"}]}, "400 invalid messages; 401/403 access; 429 request limit; 503 when assistant is disabled. Provider/budget failures may instead arrive as streamed error frames.")
add("GET", "/api/health", "Check Basic Application Health", response="{ ok: true }", notes="Public, non-versioned JSON. It is a basic liveness response, not a database-readiness probe.")


